import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import React from "react";

export const fps = 25;
export const durationInFrames = 750;

const COLORS = {
  accent: "#9EA2A8",
  light: "#F9F9FA",
  muted: "#6D7178",
  dark: "#333538",
  bg: "#0A0A0B",
  highlight: "#C9CBCF",
  green: "#22C55E",
  red: "#EF4444",
  amber: "#F5BC38",
};

const TRANSITION = 15;

// ─── Backgrounds ───────────────────────────────────────────────────────────────

const BgScene1: React.FC = () => (
  <AbsoluteFill
    style={{
      background:
        "radial-gradient(ellipse at 25% 30%, rgba(100,105,115,0.08) 0%, #0A0A0B 60%)",
    }}
  />
);

const BgScene2: React.FC = () => (
  <AbsoluteFill
    style={{
      background:
        "radial-gradient(ellipse at 75% 60%, rgba(100,105,115,0.08) 0%, #0A0A0B 60%)",
    }}
  />
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Shared Components ─────────────────────────────────────────────────────────

const GlassCard: React.FC<{
  children: React.ReactNode;
  style?: React.CSSProperties;
  delay: number;
  accentColor?: string;
}> = ({ children, style, delay, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateY = interpolate(progress, [0, 1], [50, 0]);

  return (
    <div
      style={{
        backgroundColor: "rgba(255,255,255,0.03)",
        borderRadius: 24,
        border: "1.5px solid rgba(255,255,255,0.07)",
        borderTop: accentColor
          ? `4px solid ${accentColor}`
          : "1.5px solid rgba(255,255,255,0.07)",
        padding: "40px 48px",
        opacity: progress,
        transform: `translateY(${translateY}px)`,
        ...style,
      }}
    >
      {children}
    </div>
  );
};

// ─── SCENE 1: Credibility Filter ───────────────────────────────────────────────

const FLAG_ITEMS = [
  {
    icon: "🔄",
    label: "Multiple username changes",
    sub: "Recycled or rebranded identity",
    status: "warn",
  },
  {
    icon: "📈",
    label: "New account, large following",
    sub: "Account age vs. follower ratio mismatch",
    status: "red",
  },
  {
    icon: "📍",
    label: "Location mismatch",
    sub: "Claimed city ≠ declared country",
    status: "red",
  },
];

const FlagRow: React.FC<{
  item: (typeof FLAG_ITEMS)[0];
  delay: number;
}> = ({ item, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateX = interpolate(progress, [0, 1], [40, 0]);

  const statusColor =
    item.status === "red"
      ? COLORS.red
      : item.status === "warn"
      ? COLORS.amber
      : COLORS.green;

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 36,
        opacity: progress,
        transform: `translateX(${translateX}px)`,
        padding: "28px 0",
        borderBottom: "1px solid rgba(255,255,255,0.05)",
      }}
    >
      <div
        style={{
          width: 72,
          height: 72,
          borderRadius: 18,
          backgroundColor: `${statusColor}18`,
          border: `1.5px solid ${statusColor}40`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 34,
          flexShrink: 0,
        }}
      >
        {item.icon}
      </div>
      <div style={{ flex: 1 }}>
        <div
          style={{
            fontSize: 34,
            fontWeight: 700,
            color: COLORS.light,
            marginBottom: 8,
          }}
        >
          {item.label}
        </div>
        <div style={{ fontSize: 26, fontWeight: 500, color: COLORS.muted }}>
          {item.sub}
        </div>
      </div>
      <div
        style={{
          padding: "12px 32px",
          borderRadius: 40,
          backgroundColor: `${statusColor}14`,
          border: `1.5px solid ${statusColor}50`,
          fontSize: 24,
          fontWeight: 700,
          color: statusColor,
          letterSpacing: "0.12em",
          flexShrink: 0,
        }}
      >
        {item.status === "red" ? "FLAG" : "REVIEW"}
      </div>
    </div>
  );
};

const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const titleProgress = spring({ frame, fps: f, delay: 5, config: { damping: 200 } });
  const titleY = interpolate(titleProgress, [0, 1], [-40, 0]);

  const badgeProgress = spring({ frame, fps: f, delay: 130, config: { damping: 200 } });
  const badgeScale = interpolate(badgeProgress, [0, 1], [0.88, 1]);

  return (
    <AbsoluteFill
      style={{ fontFamily: "sans-serif", alignItems: "center", justifyContent: "center" }}
    >
      <BgScene1 />

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: 2400,
          gap: 0,
        }}
      >
        {/* Title */}
        <div
          style={{
            opacity: titleProgress,
            transform: `translateY(${titleY}px)`,
            marginBottom: 64,
            textAlign: "center",
          }}
        >
          <div
            style={{
              fontSize: 28,
              fontWeight: 600,
              color: COLORS.muted,
              letterSpacing: "0.35em",
              textTransform: "uppercase",
              marginBottom: 16,
            }}
          >
            Step 1
          </div>
          <div
            style={{
              fontSize: 68,
              fontWeight: 700,
              color: COLORS.highlight,
              letterSpacing: "0.18em",
              textTransform: "uppercase",
            }}
          >
            Credibility Filter
          </div>
        </div>

        {/* Main card */}
        <div
          style={{
            backgroundColor: "rgba(255,255,255,0.03)",
            borderRadius: 28,
            border: "1.5px solid rgba(255,255,255,0.07)",
            padding: "20px 60px 8px 60px",
            width: "100%",
          }}
        >
          {/* Sub-header */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 20,
              paddingBottom: 24,
              borderBottom: "1px solid rgba(255,255,255,0.07)",
              marginBottom: 8,
            }}
          >
            <div
              style={{
                fontSize: 26,
                fontWeight: 600,
                color: COLORS.muted,
                letterSpacing: "0.18em",
                textTransform: "uppercase",
              }}
            >
              About Profile Fields — Risk Signals
            </div>
          </div>

          {FLAG_ITEMS.map((item, i) => (
            <FlagRow key={i} item={item} delay={30 + i * 20} />
          ))}
        </div>

        {/* Badge */}
        <div
          style={{
            marginTop: 60,
            opacity: badgeProgress,
            transform: `scale(${badgeScale})`,
            backgroundColor: "rgba(158,162,168,0.08)",
            border: "1.5px solid rgba(158,162,168,0.25)",
            borderRadius: 24,
            padding: "28px 80px",
            fontSize: 34,
            fontWeight: 700,
            color: COLORS.accent,
            letterSpacing: "0.16em",
            textTransform: "uppercase",
          }}
        >
          Sort & filter in a spreadsheet — in minutes
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ─── SCENE 2: Automated Vetting Pipeline ───────────────────────────────────────

const PIPELINE_NODES = [
  { icon: "🔍", label: "Scrape Profiles", sub: "Apify actor" },
  { icon: "📊", label: "Google Sheets", sub: "Auto-landing data" },
  { icon: "⚡", label: "n8n / Zapier", sub: "Trigger logic" },
  { icon: "🎯", label: "CRM / Review", sub: "Route by score" },
];

const SCORE_CRITERIA = [
  { label: "Account Age", value: 85, color: COLORS.green },
  { label: "Verification", value: 60, color: COLORS.highlight },
  { label: "Username Stability", value: 90, color: COLORS.green },
  { label: "Location Match", value: 40, color: COLORS.amber },
];

const PipelineNode: React.FC<{
  node: (typeof PIPELINE_NODES)[0];
  delay: number;
  isLast: boolean;
}> = ({ node, delay, isLast }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateY = interpolate(progress, [0, 1], [50, 0]);

  const arrowProgress = spring({
    frame,
    fps: f,
    delay: delay + 12,
    config: { damping: 200 },
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 0,
      }}
    >
      <div
        style={{
          opacity: progress,
          transform: `translateY(${translateY}px)`,
          backgroundColor: "rgba(255,255,255,0.03)",
          borderRadius: 22,
          border: "1.5px solid rgba(255,255,255,0.08)",
          padding: "32px 36px",
          textAlign: "center",
          minWidth: 240,
        }}
      >
        <div style={{ fontSize: 48, marginBottom: 14 }}>{node.icon}</div>
        <div
          style={{
            fontSize: 30,
            fontWeight: 700,
            color: COLORS.light,
            marginBottom: 8,
          }}
        >
          {node.label}
        </div>
        <div style={{ fontSize: 22, fontWeight: 500, color: COLORS.muted }}>
          {node.sub}
        </div>
      </div>

      {!isLast && (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            width: 72,
            flexShrink: 0,
          }}
        >
          <svg width="72" height="24" viewBox="0 0 72 24">
            <line
              x1="4"
              y1="12"
              x2={4 + 52 * arrowProgress}
              y2="12"
              stroke="rgba(200,205,210,0.3)"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <path
              d="M56 6l8 6-8 6"
              stroke="rgba(200,205,210,0.5)"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
              opacity={arrowProgress}
            />
          </svg>
        </div>
      )}
    </div>
  );
};

const ScoreBar: React.FC<{
  item: (typeof SCORE_CRITERIA)[0];
  delay: number;
}> = ({ item, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const barProgress = spring({
    frame,
    fps: f,
    delay: delay + 8,
    config: { damping: 200 },
  });
  const translateX = interpolate(progress, [0, 1], [-30, 0]);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 24,
        opacity: progress,
        transform: `translateX(${translateX}px)`,
      }}
    >
      <div
        style={{
          width: 220,
          fontSize: 26,
          fontWeight: 600,
          color: COLORS.muted,
          textAlign: "right",
          flexShrink: 0,
        }}
      >
        {item.label}
      </div>
      <div
        style={{
          flex: 1,
          height: 14,
          backgroundColor: "rgba(255,255,255,0.06)",
          borderRadius: 7,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: `${item.value * barProgress}%`,
            height: "100%",
            backgroundColor: item.color,
            borderRadius: 7,
            opacity: 0.75,
          }}
        />
      </div>
      <div
        style={{
          width: 72,
          fontSize: 28,
          fontWeight: 700,
          color: item.color,
          flexShrink: 0,
        }}
      >
        {Math.round(item.value * barProgress)}
      </div>
    </div>
  );
};

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const titleProgress = spring({ frame, fps: f, delay: 5, config: { damping: 200 } });
  const titleY = interpolate(titleProgress, [0, 1], [-40, 0]);

  const routeProgress = spring({ frame, fps: f, delay: 120, config: { damping: 200 } });
  const routeY = interpolate(routeProgress, [0, 1], [40, 0]);

  const badgeProgress = spring({ frame, fps: f, delay: 155, config: { damping: 200 } });
  const badgeScale = interpolate(badgeProgress, [0, 1], [0.88, 1]);

  return (
    <AbsoluteFill
      style={{ fontFamily: "sans-serif", alignItems: "center", justifyContent: "center" }}
    >
      <BgScene2 />

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: 3200,
          gap: 0,
        }}
      >
        {/* Title */}
        <div
          style={{
            opacity: titleProgress,
            transform: `translateY(${titleY}px)`,
            marginBottom: 64,
            textAlign: "center",
          }}
        >
          <div
            style={{
              fontSize: 28,
              fontWeight: 600,
              color: COLORS.muted,
              letterSpacing: "0.35em",
              textTransform: "uppercase",
              marginBottom: 16,
            }}
          >
            Step 2
          </div>
          <div
            style={{
              fontSize: 68,
              fontWeight: 700,
              color: COLORS.highlight,
              letterSpacing: "0.18em",
              textTransform: "uppercase",
            }}
          >
            Automated Vetting Pipeline
          </div>
        </div>

        {/* Pipeline row */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            marginBottom: 56,
          }}
        >
          {PIPELINE_NODES.map((node, i) => (
            <PipelineNode
              key={i}
              node={node}
              delay={20 + i * 18}
              isLast={i === PIPELINE_NODES.length - 1}
            />
          ))}
        </div>

        {/* Score + Route row */}
        <div
          style={{
            display: "flex",
            gap: 48,
            width: "100%",
            opacity: routeProgress,
            transform: `translateY(${routeY}px)`,
          }}
        >
          {/* Score criteria card */}
          <div
            style={{
              flex: 1.4,
              backgroundColor: "rgba(255,255,255,0.03)",
              borderRadius: 24,
              border: "1.5px solid rgba(255,255,255,0.07)",
              padding: "40px 48px",
              display: "flex",
              flexDirection: "column",
              gap: 28,
            }}
          >
            <div
              style={{
                fontSize: 26,
                fontWeight: 600,
                color: COLORS.muted,
                letterSpacing: "0.2em",
                textTransform: "uppercase",
                marginBottom: 4,
              }}
            >
              Credibility Score Components
            </div>
            {SCORE_CRITERIA.map((item, i) => (
              <ScoreBar key={i} item={item} delay={128 + i * 10} />
            ))}
          </div>

          {/* Routing card */}
          <div
            style={{
              flex: 1,
              backgroundColor: "rgba(255,255,255,0.03)",
              borderRadius: 24,
              border: "1.5px solid rgba(255,255,255,0.07)",
              padding: "40px 48px",
              display: "flex",
              flexDirection: "column",
              gap: 28,
            }}
          >
            <div
              style={{
                fontSize: 26,
                fontWeight: 600,
                color: COLORS.muted,
                letterSpacing: "0.2em",
                textTransform: "uppercase",
                marginBottom: 4,
              }}
            >
              Auto-Routing Logic
            </div>

            {/* Above threshold */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 28,
                padding: "28px 32px",
                borderRadius: 18,
                backgroundColor: "rgba(34,197,94,0.06)",
                border: "1.5px solid rgba(34,197,94,0.2)",
              }}
            >
              <div style={{ fontSize: 40 }}>✅</div>
              <div>
                <div
                  style={{
                    fontSize: 28,
                    fontWeight: 700,
                    color: COLORS.green,
                    marginBottom: 6,
                  }}
                >
                  Above threshold
                </div>
                <div style={{ fontSize: 24, fontWeight: 500, color: COLORS.muted }}>
                  → Add to outreach CRM
                </div>
              </div>
            </div>

            {/* Below threshold */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 28,
                padding: "28px 32px",
                borderRadius: 18,
                backgroundColor: "rgba(239,68,68,0.06)",
                border: "1.5px solid rgba(239,68,68,0.2)",
              }}
            >
              <div style={{ fontSize: 40 }}>🚩</div>
              <div>
                <div
                  style={{
                    fontSize: 28,
                    fontWeight: 700,
                    color: COLORS.red,
                    marginBottom: 6,
                  }}
                >
                  Below threshold
                </div>
                <div style={{ fontSize: 24, fontWeight: 500, color: COLORS.muted }}>
                  → Flag for manual review
                </div>
              </div>
            </div>

            {/* Trigger */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 16,
                padding: "20px 32px",
                borderRadius: 18,
                backgroundColor: "rgba(255,255,255,0.03)",
                border: "1.5px solid rgba(255,255,255,0.07)",
              }}
            >
              <div style={{ fontSize: 30 }}>🔁</div>
              <div style={{ fontSize: 24, fontWeight: 500, color: COLORS.muted }}>
                Runs on every new batch
              </div>
            </div>
          </div>
        </div>

        {/* Badge */}
        <div
          style={{
            marginTop: 60,
            opacity: badgeProgress,
            transform: `scale(${badgeScale})`,
            backgroundColor: "rgba(158,162,168,0.07)",
            border: "1.5px solid rgba(158,162,168,0.22)",
            borderRadius: 24,
            padding: "28px 80px",
            fontSize: 34,
            fontWeight: 700,
            color: COLORS.accent,
            letterSpacing: "0.14em",
            textTransform: "uppercase",
          }}
