// ─── Root ──────────────────────────────────────────────────────────────────────

const MyVideo: React.FC = () => (
  <TransitionSeries>
    <TransitionSeries.Sequence durationInFrames={20}>
      <BlackScreen />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: 20 })}
    />

    <TransitionSeries.Sequence durationInFrames={340 + TRANSITION}>
      <SceneOne />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={355 + TRANSITION}>
      <SceneTwo />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: 20 })}
    />

    <TransitionSeries.Sequence durationInFrames={20}>
      <BlackScreen />
    </TransitionSeries.Sequence>
  </TransitionSeries>
);

export default MyVideo;
